// 图标栏 + 二级面板：最左侧的窄图标栏切换第一级菜单（模块），旁边是模块内的导航。
// 适合客服、IM、项目管理这类工作台。

import { pageUnder, Slot, type TabsOutletProps, useLayoutState, useNavigation } from "@go-tenon/shell"
import { useRouter } from "@tanstack/react-router"
import type { ReactNode } from "react"
import { badgeText, Crumbs, MenuIcon, NavLink } from "@/components/tenon/nav"
import { LayoutContent } from "@/components/tenon/tab-bar"
import { Button } from "@/components/ui/button"
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from "@/components/ui/tooltip"
import { cn } from "@/lib/utils"

/** RailLayout 的选项。 */
export interface RailLayoutProps {
  logo?: ReactNode
  tabs?: boolean | TabsOutletProps
}

/** 图标栏 + 二级面板。二级面板的宽度保存在布局状态中（secondaryWidth）。插槽与侧栏布局相同。 */
export function RailLayout({ logo, tabs }: RailLayoutProps): ReactNode {
  const nav = useNavigation()
  const router = useRouter()
  const [state] = useLayoutState()
  return (
    <TooltipProvider>
      <div className="flex min-h-svh">
        <aside className="flex w-14 shrink-0 flex-col items-center gap-2 border-r bg-sidebar py-3">
          {logo}
          {nav.modules.map((m) => (
            <Tooltip key={m.id}>
              <TooltipTrigger asChild>
                <Button
                  variant={nav.module?.id === m.id ? "default" : "ghost"}
                  size="icon"
                  aria-label={m.title}
                  onClick={() => void router.navigate({ href: pageUnder(nav.menu, m.path) ?? m.path })}
                >
                  <MenuIcon item={m} />
                  {!m.icon && <span>{m.title.slice(0, 1)}</span>}
                </Button>
              </TooltipTrigger>
              <TooltipContent side="right">{m.title}</TooltipContent>
            </Tooltip>
          ))}
          <div className="mt-auto">
            <Slot name="user" />
          </div>
        </aside>
        {nav.secondary.length > 0 && (
          <nav
            className="flex shrink-0 flex-col gap-1 border-r bg-sidebar/50 p-2"
            style={{ width: state.secondaryWidth ?? 220 }}
          >
            <div className="px-2 py-1.5 text-xs font-medium text-muted-foreground">{nav.module?.title}</div>
            {nav.secondary.flatMap((item) =>
              (item.children ?? [item]).map((leaf) => (
                <NavLink
                  key={leaf.id}
                  to={leaf.path}
                  className={cn(
                    "flex items-center gap-2 rounded-md px-2 py-1.5 text-sm hover:bg-muted",
                    nav.active.includes(leaf.id) && "bg-muted font-medium",
                  )}
                >
                  <MenuIcon item={leaf} className="size-4" />
                  <span className="truncate">{leaf.title}</span>
                  {badgeText(leaf.badge) && <span className="ml-auto text-xs">{badgeText(leaf.badge)}</span>}
                </NavLink>
              )),
            )}
          </nav>
        )}
        <div className="flex min-w-0 flex-1 flex-col">
          <header className="flex h-14 items-center gap-2 border-b px-4">
            <Crumbs />
            <div className="ml-auto flex items-center gap-2">
              <Slot name="search" />
              <Slot name="actions" />
              <Slot name="tenant" />
            </div>
          </header>
          <main className={tabs ? "flex flex-1 flex-col" : "flex flex-1 flex-col gap-4 p-4"}>
            <LayoutContent tabs={tabs} />
          </main>
        </div>
      </div>
    </TooltipProvider>
  )
}

// 布局共用的部件：应用内的链接、面包屑、图标。由 tenon 的 shadcn registry 提供，加入项目后可以随意修改。

import { type MenuItem, pageUnder, useNavigation } from "@go-tenon/shell"
import { useRouter } from "@tanstack/react-router"
import {
  AppWindow,
  Bell,
  ChartColumn,
  FileText,
  Folder,
  House,
  LayoutDashboard,
  type LucideIcon,
  MessageSquare,
  Settings,
  Shield,
  ShoppingCart,
  Store,
  User,
  Users,
} from "lucide-react"
import { Fragment, type MouseEvent, type ReactNode } from "react"
import {
  Breadcrumb,
  BreadcrumbItem,
  BreadcrumbLink,
  BreadcrumbList,
  BreadcrumbPage,
  BreadcrumbSeparator,
} from "@/components/ui/breadcrumb"

/**
 * 路由元数据中 icon 的名字到 lucide 图标的映射。名字与运营后台（@go-tenon/admin 的 defaultIcons）相同，
 * 同一份路由元数据在两套外观中都能显示图标。需要别的图标时加在这里。
 */
export const icons: Record<string, LucideIcon> = {
  appstore: AppWindow,
  "bar-chart": ChartColumn,
  bell: Bell,
  dashboard: LayoutDashboard,
  "file-text": FileText,
  folder: Folder,
  home: House,
  message: MessageSquare,
  safety: Shield,
  setting: Settings,
  shop: Store,
  "shopping-cart": ShoppingCart,
  team: Users,
  user: User,
}

/** 菜单项的图标；没有登记的名字不显示。 */
export function MenuIcon({ item, className }: { item: Pick<MenuItem, "icon">; className?: string }): ReactNode {
  const Icon = item.icon ? icons[item.icon] : undefined
  return Icon ? <Icon className={className} /> : null
}

/** 应用内的链接：保留浏览器的默认行为（新窗口打开等），普通点击由路由跳转。 */
export function NavLink({
  to,
  children,
  className,
  ...rest
}: { to: string; children: ReactNode; className?: string } & Omit<React.ComponentProps<"a">, "href">): ReactNode {
  const router = useRouter()
  const onClick = (e: MouseEvent<HTMLAnchorElement>) => {
    rest.onClick?.(e)
    if (e.defaultPrevented || e.button !== 0 || e.metaKey || e.ctrlKey || e.shiftKey || e.altKey) return
    e.preventDefault()
    void router.navigate({ href: to })
  }
  return (
    <a {...rest} href={router.buildLocation({ href: to } as never).href} className={className} onClick={onClick}>
      {children}
    </a>
  )
}

/** 面包屑：最后一级是当前页面；分组跳到它下面第一个可以进入的页面。 */
export function Crumbs(): ReactNode {
  const { crumbs, menu } = useNavigation()
  if (crumbs.length === 0) return null
  return (
    <Breadcrumb>
      <BreadcrumbList>
        {crumbs.map((c, i) => {
          const last = i === crumbs.length - 1
          const target = last ? undefined : pageUnder(menu, c.path)
          return (
            <Fragment key={c.path}>
              <BreadcrumbItem>
                {last ? (
                  <BreadcrumbPage>{c.title}</BreadcrumbPage>
                ) : target ? (
                  <BreadcrumbLink asChild>
                    <NavLink to={target}>{c.title}</NavLink>
                  </BreadcrumbLink>
                ) : (
                  c.title
                )}
              </BreadcrumbItem>
              {!last && <BreadcrumbSeparator />}
            </Fragment>
          )
        })}
      </BreadcrumbList>
    </Breadcrumb>
  )
}

/** 菜单项的徽标文字：数字、文字，true 是小红点。 */
export function badgeText(badge: MenuItem["badge"]): string | undefined {
  if (badge === undefined || badge === false) return undefined
  return badge === true ? "•" : String(badge)
}

// 标签栏：@go-tenon/shell 多标签模型（useTabs）的 shadcn 外观。每个标签的菜单（右键或点击箭头）中是刷新、固定和关闭，
// 拖动排序用浏览器原生的拖放。

import { TabsOutlet, type TabsOutletProps, type TabView, useTabs } from "@go-tenon/shell"
import { Outlet } from "@tanstack/react-router"
import { ChevronDown, Pin, X } from "lucide-react"
import { type ReactNode, useState } from "react"
import { MenuIcon } from "@/components/tenon/nav"
import { Button } from "@/components/ui/button"
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"
import { cn } from "@/lib/utils"

function Tab({ tab, index }: { tab: TabView; index: number }): ReactNode {
  const tabs = useTabs()
  const [menuOpen, setMenuOpen] = useState(false)
  return (
    <div
      role="tab"
      aria-selected={tab.active}
      tabIndex={tab.active ? 0 : -1}
      data-tab-key={tab.key}
      draggable
      onDragStart={(e) => e.dataTransfer.setData("text/tenon-tab", tab.key)}
      onDragOver={(e) => e.preventDefault()}
      onDrop={(e) => {
        const from = e.dataTransfer.getData("text/tenon-tab")
        if (from && from !== tab.key) tabs.move(from, tab.key)
      }}
      onContextMenu={(e) => {
        e.preventDefault()
        setMenuOpen(true)
      }}
      onKeyDown={(e) => {
        if (e.key === "Enter" || e.key === " ") void tabs.activate(tab.key)
      }}
      className={cn(
        "group flex h-8 shrink-0 cursor-pointer items-center gap-1.5 rounded-md border px-2 text-sm",
        tab.active
          ? "bg-background text-foreground shadow-xs"
          : "bg-muted/50 text-muted-foreground hover:text-foreground",
      )}
      onClick={() => void tabs.activate(tab.key)}
    >
      {tab.pinned && <Pin className="size-3" />}
      <MenuIcon item={tab} className="size-3.5" />
      <span className="max-w-40 truncate">{tab.title}</span>
      {tab.dirty && <span className="size-1.5 rounded-full bg-amber-500" title="有未保存的修改" />}
      <DropdownMenu open={menuOpen} onOpenChange={setMenuOpen}>
        <DropdownMenuTrigger asChild>
          <button
            type="button"
            aria-label={`${tab.title} 的操作`}
            className="opacity-50 hover:opacity-100"
            onClick={(e) => e.stopPropagation()}
          >
            <ChevronDown className="size-3" />
          </button>
        </DropdownMenuTrigger>
        <DropdownMenuContent align="start" onClick={(e) => e.stopPropagation()}>
          <DropdownMenuItem onSelect={() => void tabs.refresh(tab.key)}>刷新</DropdownMenuItem>
          <DropdownMenuItem onSelect={() => (tab.pinned ? tabs.unpin(tab.key) : tabs.pin(tab.key))}>
            {tab.pinned ? "取消固定" : "固定"}
          </DropdownMenuItem>
          <DropdownMenuSeparator />
          <DropdownMenuItem disabled={!tab.closable} onSelect={() => void tabs.close(tab.key)}>
            关闭
          </DropdownMenuItem>
          <DropdownMenuItem disabled={tabs.tabs.length <= 1} onSelect={() => void tabs.closeOthers(tab.key)}>
            关闭其他
          </DropdownMenuItem>
          <DropdownMenuItem disabled={index === tabs.tabs.length - 1} onSelect={() => void tabs.closeRight(tab.key)}>
            关闭右侧
          </DropdownMenuItem>
          <DropdownMenuItem onSelect={() => void tabs.closeAll()}>关闭全部</DropdownMenuItem>
        </DropdownMenuContent>
      </DropdownMenu>
      {tab.closable && (
        <Button
          variant="ghost"
          size="icon"
          className="size-4 rounded-sm"
          aria-label={`关闭 ${tab.title}`}
          onClick={(e) => {
            e.stopPropagation()
            void tabs.close(tab.key)
          }}
        >
          <X className="size-3" />
        </Button>
      )}
    </div>
  )
}

/** 多标签的标签栏，放在页面区域的上方（布局的 tabs 开启时自动放置）。 */
export function TabBar({ className }: { className?: string }): ReactNode {
  const tabs = useTabs()
  if (tabs.tabs.length === 0) return null
  return (
    <div role="tablist" className={cn("flex gap-1 overflow-x-auto border-b bg-muted/30 px-3 py-1.5", className)}>
      {tabs.tabs.map((tab, index) => (
        <Tab key={tab.key} tab={tab} index={index} />
      ))}
    </div>
  )
}

/** 页面区域：多标签时是标签栏和 TabsOutlet，否则是 Outlet。 */
export function LayoutContent({ tabs }: { tabs?: boolean | TabsOutletProps }): ReactNode {
  if (!tabs) return <Outlet />
  return (
    <>
      <TabBar />
      <TabsOutlet {...(typeof tabs === "object" ? tabs : {})} />
    </>
  )
}
